import { filterVolumes } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function expectRange(fn: () => unknown, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

const volumes = [
  { id: 1, title: '  TypeScript Guide  ' },
  { id: 2, title: 'Cooking' },
  { id: 1, title: 'typescript patterns' },
  { id: 3, title: 'Script Notes' }
];
const before = JSON.stringify(volumes);
const matches = filterVolumes(volumes, '  TYPESCRIPT  ');
deepEqual(matches, [
  { id: 1, title: 'TypeScript Guide' },
  { id: 1, title: 'typescript patterns' }
], 'matching is trimmed, case-insensitive, ordered, and preserves duplicates');
assert(JSON.stringify(volumes) === before, 'input array and volumes are not mutated');
assert(matches !== volumes, 'result array is new');
assert(matches[0] !== volumes[0], 'matched volume is newly allocated');

const all = filterVolumes(volumes, '   ');
deepEqual(all, [
  { id: 1, title: 'TypeScript Guide' },
  { id: 2, title: 'Cooking' },
  { id: 1, title: 'typescript patterns' },
  { id: 3, title: 'Script Notes' }
], 'blank query returns every volume with trimmed titles');
assert(all.every((volume, index) => volume !== volumes[index]), 'every returned volume is newly allocated');
all[0] = { id: 99, title: 'changed' };
deepEqual(filterVolumes(volumes, 'typescript'), matches, 'result mutation does not affect later results');
deepEqual(filterVolumes([], 'anything'), [], 'empty input returns an empty array');

expectRange(() => filterVolumes([{ id: 0, title: 'valid' }], ''), 'zero ID is rejected');
expectRange(() => filterVolumes([{ id: -1, title: 'valid' }], ''), 'negative ID is rejected');
expectRange(() => filterVolumes([{ id: 1.5, title: 'valid' }], ''), 'fractional ID is rejected');
expectRange(() => filterVolumes([{ id: Number.MAX_SAFE_INTEGER + 1, title: 'valid' }], ''), 'unsafe ID is rejected');
expectRange(() => filterVolumes([{ id: 1, title: '   ' }], ''), 'blank title is rejected');
expectRange(() => filterVolumes([
  { id: 1, title: 'matching' },
  { id: 0, title: 'not matching' }
], 'matching'), 'every volume is validated even when a malformed volume would not match');

